<?php
session_start(); if(!isset($_SESSION['user_id']) || (($_SESSION['role']??'')!='admin')){ header('Location: login.php'); exit; }
$raw=json_decode(file_get_contents(__DIR__.'/fake_db.json'),true); $comps=array_reverse($raw['complaints']??[]);
$total=count($comps); $pending=0; $inprog=0; $resolved=0; $closed=0; $hostel=0; $acad=0;
foreach($comps as $c){ $s=strtolower($c['status']); if($s=='pending'||$s=='open') $pending++; if($s=='in progress') $inprog++; if($s=='resolved') $resolved++; if($s=='closed') $closed++; if(strtolower($c['category'])=='hostel') $hostel++; if(strtolower($c['category'])=='academics') $acad++; }
